// Driving paths (pamphlet routes) for the admin Outreach tab: pure helpers, unit-tested in
// test/routes.test.js. The route plan itself is generated by _internal/outreach/source/make_route_plan.py
// (config key out_json) and bundled with the function; progress lives in the settings store.

// Prospect industry -> the pamphlet to hand out (file names in _internal/outreach/pamphlets/).
const PAMPHLET_FOR = {
  "Gyms and fitness centers": "Gyms and fitness",
  "CrossFit and performance gyms": "CrossFit and performance",
  "Sports teams and athletic programs": "Sports teams and clubs",
  "High schools and colleges (athletics)": "High schools and colleges",
  "Recovery studios and med spas": "Recovery studios and med spas",
  "Physical therapy, chiropractic, and sports medicine": "Physical therapy and chiropractic",
  "Physical therapy and chiropractic clinics": "Physical therapy and chiropractic",
  "Salons and beauty studios": "Salons and day spas",
};
const pamphletFor = (industry) => PAMPHLET_FOR[industry] || industry || "Other";

// Businesses on a day: every stop plus any "also at this address" business, which gets its own pamphlet.
function businessesOn(day) {
  return (day.stops || []).reduce((n, s) => n + 1 + ((s.also && s.also.length) || 0), 0);
}

// Pamphlets to take for a day: one per business, grouped by pamphlet, busiest first.
function pamphletsFor(day) {
  const counts = {};
  (day.stops || []).forEach((s) => {
    const p = pamphletFor(s.industry);
    counts[p] = (counts[p] || 0) + 1 + ((s.also && s.also.length) || 0);
  });
  const byPamphlet = Object.keys(counts).map((pamphlet) => ({ pamphlet, count: counts[pamphlet] })).sort((a, b) => b.count - a.count || a.pamphlet.localeCompare(b.pamphlet));
  return { total: byPamphlet.reduce((n, x) => n + x.count, 0), byPamphlet };
}

const emptyProgress = () => ({ days: {} });
function normalizeProgress(p) {
  const out = emptyProgress();
  const days = (p && p.days) || {};
  Object.keys(days).forEach((k) => {
    const d = days[k] || {};
    out.days[k] = {
      completed: !!d.completed,
      completedAt: d.completed && typeof d.completedAt === "string" ? d.completedAt : null,
      delivered: Array.isArray(d.delivered) ? [...new Set(d.delivered.filter((x) => typeof x === "string"))] : [],
      note: typeof d.note === "string" ? d.note.slice(0, 500) : "",
    };
  });
  return out;
}

// Apply an admin edit to one day. `completed: true` with no `delivered` list marks every stop delivered;
// `completed: false` keeps whatever stops were already ticked. Unknown stop ids are dropped.
function applyPatch(progress, day, patch, now) {
  const p = normalizeProgress(progress);
  const key = String(day.n);
  const cur = p.days[key] || { completed: false, completedAt: null, delivered: [], note: "" };
  const known = new Set((day.stops || []).map((s) => s.id));
  if (Array.isArray(patch.delivered)) cur.delivered = [...new Set(patch.delivered.filter((id) => known.has(id)))];
  if (typeof patch.note === "string") cur.note = patch.note.trim().slice(0, 500);
  if (typeof patch.completed === "boolean") {
    if (patch.completed && !Array.isArray(patch.delivered)) cur.delivered = [...known];
    cur.completed = patch.completed;
    cur.completedAt = patch.completed ? (cur.completedAt || now) : null;
  }
  p.days[key] = cur;
  return p;
}

// Headline numbers for the tab: businesses reached, routes done, and the per-day roll-up.
function summarize(plan, progress) {
  const p = normalizeProgress(progress);
  let stops = 0, delivered = 0, daysDone = 0;
  const days = (plan.days || []).map((day) => {
    const d = p.days[String(day.n)] || { completed: false, delivered: [] };
    const ids = new Set((day.stops || []).map((s) => s.id));
    const done = d.delivered.filter((id) => ids.has(id)).length;
    stops += ids.size; delivered += done; if (d.completed) daysDone += 1;
    return { n: day.n, delivered: done, stops: ids.size, completed: !!d.completed, completedAt: d.completedAt || null, note: d.note || "", pamphlets: pamphletsFor(day) };
  });
  return { stops, delivered, pct: stops ? Math.round((delivered / stops) * 100) : 0, days: (plan.days || []).length, daysDone, byDay: days };
}

module.exports = { PAMPHLET_FOR, pamphletFor, businessesOn, pamphletsFor, normalizeProgress, applyPatch, summarize };
